exercises.solution:
def memoize(func):
    cache = {}

    def wrapper(*args):
        if args not in cache:
            wrapper.calls += 1
            cache[args] = func(*args)
        return cache[args]

    wrapper.calls = 0
    return wrapper


@memoize
def fib(n):
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)


def check(n):
    return [fib(n), fib.calls]
